-- Create "assignments" table
CREATE TABLE "assignments" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "title" character varying NOT NULL, "description" text NULL, "instructions" text NULL, "assignment_type" character varying NOT NULL DEFAULT 'worksheet', "available_from" timestamptz NULL, "due_at" timestamptz NULL, "late_submission_allowed" boolean NOT NULL DEFAULT true, "max_attempts" bigint NULL, "maximum_marks" numeric(8,2) NULL, "status" character varying NOT NULL DEFAULT 'draft', "academic_session_id" uuid NOT NULL, "teacher_id" uuid NOT NULL, "subject_offering_id" uuid NULL, "content_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "assignments_academic_sessions_academic_session" FOREIGN KEY ("academic_session_id") REFERENCES "academic_sessions" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "assignments_content_items_content" FOREIGN KEY ("content_id") REFERENCES "content_items" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "assignments_subject_offerings_subject_offering" FOREIGN KEY ("subject_offering_id") REFERENCES "subject_offerings" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "assignments_teachers_teacher" FOREIGN KEY ("teacher_id") REFERENCES "teachers" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "assignments_marks_not_negative" CHECK ((maximum_marks IS NULL) OR (maximum_marks >= (0)::numeric)), CONSTRAINT "assignments_window" CHECK ((available_from IS NULL) OR (due_at IS NULL) OR (due_at >= available_from)));
-- Create index "assignment_academic_session_id_due_at" to table: "assignments"
CREATE INDEX "assignment_academic_session_id_due_at" ON "assignments" ("academic_session_id", "due_at");
-- Create index "assignment_status_due_at" to table: "assignments"
CREATE INDEX "assignment_status_due_at" ON "assignments" ("status", "due_at");
-- Create index "assignment_subject_offering_id_status" to table: "assignments"
CREATE INDEX "assignment_subject_offering_id_status" ON "assignments" ("subject_offering_id", "status");
-- Create index "assignment_teacher_id_academic_session_id_due_at" to table: "assignments"
CREATE INDEX "assignment_teacher_id_academic_session_id_due_at" ON "assignments" ("teacher_id", "academic_session_id", "due_at");
-- Create "assignment_items" table
CREATE TABLE "assignment_items" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "question_id" uuid NULL, "position" bigint NOT NULL, "marks" numeric(8,2) NULL, "required" boolean NOT NULL DEFAULT true, "assignment_id" uuid NOT NULL, "content_item_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "assignment_items_assignments_items" FOREIGN KEY ("assignment_id") REFERENCES "assignments" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "assignment_items_content_items_content_item" FOREIGN KEY ("content_item_id") REFERENCES "content_items" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "assignment_items_marks_not_negative" CHECK ((marks IS NULL) OR (marks >= (0)::numeric)));
-- Create index "assignmentitem_assignment_id_position" to table: "assignment_items"
CREATE INDEX "assignmentitem_assignment_id_position" ON "assignment_items" ("assignment_id", "position");
-- Create "assignment_submissions" table
CREATE TABLE "assignment_submissions" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "attempt_number" bigint NOT NULL DEFAULT 1, "submitted_at" timestamptz NULL, "status" character varying NOT NULL DEFAULT 'draft', "late" boolean NOT NULL DEFAULT false, "total_marks" numeric(8,2) NULL, "marks_obtained" numeric(8,2) NULL, "graded_at" timestamptz NULL, "assignment_id" uuid NOT NULL, "student_id" uuid NOT NULL, "graded_by" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "assignment_submissions_assignments_submissions" FOREIGN KEY ("assignment_id") REFERENCES "assignments" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "assignment_submissions_persons_grader" FOREIGN KEY ("graded_by") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "assignment_submissions_students_student" FOREIGN KEY ("student_id") REFERENCES "students" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "assignment_submissions_graded_has_marks" CHECK (((status)::text <> 'graded'::text) OR (marks_obtained IS NOT NULL)), CONSTRAINT "assignment_submissions_marks_not_negative" CHECK ((marks_obtained IS NULL) OR (marks_obtained >= (0)::numeric)));
-- Create index "assignmentsubmission_assignment_id_student_id_attempt_number" to table: "assignment_submissions"
CREATE UNIQUE INDEX "assignmentsubmission_assignment_id_student_id_attempt_number" ON "assignment_submissions" ("assignment_id", "student_id", "attempt_number");
-- Create index "assignmentsubmission_assignment_id_student_id_status" to table: "assignment_submissions"
CREATE INDEX "assignmentsubmission_assignment_id_student_id_status" ON "assignment_submissions" ("assignment_id", "student_id", "status");
-- Create index "assignmentsubmission_student_id_status" to table: "assignment_submissions"
CREATE INDEX "assignmentsubmission_student_id_status" ON "assignment_submissions" ("student_id", "status");
-- Create "assignment_submission_items" table
CREATE TABLE "assignment_submission_items" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "response_text" text NULL, "question_response_id" uuid NULL, "marks_obtained" numeric(8,2) NULL, "feedback" text NULL, "assignment_item_id" uuid NOT NULL, "submission_id" uuid NOT NULL, "asset_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "assignment_submission_items_assets_asset" FOREIGN KEY ("asset_id") REFERENCES "assets" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "assignment_submission_items_assignment_items_responses" FOREIGN KEY ("assignment_item_id") REFERENCES "assignment_items" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "assignment_submission_items_assignment_submissions_items" FOREIGN KEY ("submission_id") REFERENCES "assignment_submissions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "assignment_submission_items_marks_not_negative" CHECK ((marks_obtained IS NULL) OR (marks_obtained >= (0)::numeric)));
-- Create index "assignmentsubmissionitem_submission_id_assignment_item_id" to table: "assignment_submission_items"
CREATE UNIQUE INDEX "assignmentsubmissionitem_submission_id_assignment_item_id" ON "assignment_submission_items" ("submission_id", "assignment_item_id");
-- Create "assignment_targets" table
CREATE TABLE "assignment_targets" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "target_type" character varying NOT NULL, "target_id" uuid NOT NULL, "assignment_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "assignment_targets_assignments_targets" FOREIGN KEY ("assignment_id") REFERENCES "assignments" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "assignmenttarget_assignment_id_target_type_target_id" to table: "assignment_targets"
CREATE UNIQUE INDEX "assignmenttarget_assignment_id_target_type_target_id" ON "assignment_targets" ("assignment_id", "target_type", "target_id");
-- Create index "assignmenttarget_target_type_target_id_assignment_id" to table: "assignment_targets"
CREATE INDEX "assignmenttarget_target_type_target_id_assignment_id" ON "assignment_targets" ("target_type", "target_id", "assignment_id");
-- Create "stream_posts" table
CREATE TABLE "stream_posts" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "post_type" character varying NOT NULL DEFAULT 'announcement', "title" character varying NULL, "body" text NOT NULL, "pinned" boolean NOT NULL DEFAULT false, "published_at" timestamptz NULL, "expires_at" timestamptz NULL, "status" character varying NOT NULL DEFAULT 'draft', "author_person_id" uuid NOT NULL, "academic_session_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "stream_posts_academic_sessions_academic_session" FOREIGN KEY ("academic_session_id") REFERENCES "academic_sessions" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "stream_posts_persons_author" FOREIGN KEY ("author_person_id") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "stream_posts_window" CHECK ((expires_at IS NULL) OR (published_at IS NULL) OR (expires_at > published_at)));
-- Create index "streampost_academic_session_id_published_at" to table: "stream_posts"
CREATE INDEX "streampost_academic_session_id_published_at" ON "stream_posts" ("academic_session_id", "published_at");
-- Create index "streampost_author_person_id_created_at" to table: "stream_posts"
CREATE INDEX "streampost_author_person_id_created_at" ON "stream_posts" ("author_person_id", "created_at");
-- Create index "streampost_pinned_published_at" to table: "stream_posts"
CREATE INDEX "streampost_pinned_published_at" ON "stream_posts" ("pinned", "published_at");
-- Create index "streampost_status_published_at" to table: "stream_posts"
CREATE INDEX "streampost_status_published_at" ON "stream_posts" ("status", "published_at");
-- Create "stream_comments" table
CREATE TABLE "stream_comments" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "body" text NOT NULL, "status" character varying NOT NULL DEFAULT 'visible', "author_person_id" uuid NOT NULL, "post_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "stream_comments_persons_author" FOREIGN KEY ("author_person_id") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "stream_comments_stream_posts_comments" FOREIGN KEY ("post_id") REFERENCES "stream_posts" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "streamcomment_author_person_id_created_at" to table: "stream_comments"
CREATE INDEX "streamcomment_author_person_id_created_at" ON "stream_comments" ("author_person_id", "created_at");
-- Create index "streamcomment_post_id_created_at" to table: "stream_comments"
CREATE INDEX "streamcomment_post_id_created_at" ON "stream_comments" ("post_id", "created_at");
-- Create "stream_targets" table
CREATE TABLE "stream_targets" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "target_type" character varying NOT NULL, "target_id" uuid NOT NULL, "post_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "stream_targets_stream_posts_targets" FOREIGN KEY ("post_id") REFERENCES "stream_posts" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "streamtarget_post_id_target_type_target_id" to table: "stream_targets"
CREATE UNIQUE INDEX "streamtarget_post_id_target_type_target_id" ON "stream_targets" ("post_id", "target_type", "target_id");
